#[inline]
fn destack_debug_inspector_endpoint_replay(
    binding: &BindingCallContext,
    out: *mut InspectorEndpoint,
    handle: resource::InspectorHandle,
) -> RuntimeResult<()> {
    let _ = &handle;

    binding.trace().run_binding_without_context(
        DEBUG_INSPECTOR_ENDPOINT,
        binding.replay_payload_for(DEBUG_INSPECTOR_ENDPOINT)?,
        || unsafe {
            platform_runtime_native::destack_debug_inspector_endpoint(binding, out, handle)
        },
        |result| {
            if let Ok(()) = result {
                let result_value = unsafe {
                    if out.is_null() {
                        return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
                    }
                    *out
                };
                let result_recorded_url = unsafe { result_value.url.as_str()? }.to_string();
                let result_recorded_process_id = result_value.process_id;
                let result_recorded = InspectorEndpointReplayRecord {
                    url: result_recorded_url,
                    process_id: result_recorded_process_id,
                };
                let payload = DebugInspectorEndpointReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    DebugInspectorEndpointReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native_url = binding.store_string(&value.url);
                    let value_native_process_id = value.process_id;
                    let value_native = InspectorEndpoint {
                        url: value_native_url,
                        process_id: value_native_process_id,
                    };
                    unsafe {
                        std::ptr::write(out, value_native);
                    }
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

